import{_ as e,o as n,c as a,j as t,a as l,a2 as o}from"./chunks/framework.CXZjg2r3.js";const u=JSON.parse('{"title":"🟢 第 1 章 · 注册与工具链","description":"","frontmatter":{},"headers":[],"relativePath":"miniapp/01-register-and-tools.md","filePath":"miniapp/01-register-and-tools.md","lastUpdated":1792667591000}'),r={name:"miniapp/01-register-and-tools.md"};function i(p,s,d,c,g,h){return n(),a("div",null,[...s[0]||(s[0]=[t("h1",{id:"🟢-第-1-章-·-注册与工具链",tabindex:"-1"},[l("🟢 第 1 章 · 注册与工具链 "),t("a",{class:"header-anchor",href:"#🟢-第-1-章-·-注册与工具链","aria-label":'Permalink to "🟢 第 1 章 · 注册与工具链"'},"​")],-1),t("div",{class:"tip custom-block"},[t("p",{class:"custom-block-title"},"本章信息"),t("p",null,"难度：🟢 入门 · 预计学习 40 分钟 · 前置：第 0 章 · 环境搭建")],-1),t("svg",{viewBox:"0 0 760 240",xmlns:"http://www.w3.org/2000/svg",width:"100%",role:"img","aria-label":"第1章漫画：注册与工具链"},[t("rect",{x:"10",y:"10",width:"365",height:"220",rx:"12",fill:"#F8FAFC",stroke:"#E2E8F0"}),t("text",{x:"28",y:"36","font-size":"14",fill:"#94A3B8","font-family":"sans-serif"},"1"),t("path",{d:"M 78 137 Q 84 122 94 120",stroke:"#3B82F6","stroke-width":"3",fill:"none","stroke-linecap":"round"}),t("circle",{cx:"80",cy:"160",r:"24",fill:"#3B82F6"}),t("rect",{x:"50",y:"184",width:"60",height:"40",rx:"18",fill:"#3B82F6"}),t("circle",{cx:"71",cy:"156",r:"2.5",fill:"#0F172A"}),t("circle",{cx:"89",cy:"156",r:"2.5",fill:"#0F172A"}),t("path",{d:"M 70 170 Q 75 175 80 170 Q 85 165 90 170",stroke:"#0F172A","stroke-width":"2",fill:"none","stroke-linecap":"round"}),t("rect",{x:"130",y:"46",width:"216",height:"94",rx:"10",fill:"#FFFFFF",stroke:"#CBD5E1"}),t("path",{d:"M 138 140 L 104 156 L 176 140 Z",fill:"#FFFFFF",stroke:"#CBD5E1"}),t("text",{x:"148",y:"72","font-size":"13",fill:"#334155","font-family":"sans-serif"},"工具装好了"),t("text",{x:"148",y:"96","font-size":"13",fill:"#334155","font-family":"sans-serif"},"可项目从哪儿来呀"),t("text",{x:"148",y:"120","font-size":"13",fill:"#334155","font-family":"sans-serif"},"AppID 又是个啥"),t("rect",{x:"385",y:"10",width:"365",height:"220",rx:"12",fill:"#F8FAFC",stroke:"#E2E8F0"}),t("text",{x:"403",y:"36","font-size":"14",fill:"#94A3B8","font-family":"sans-serif"},"2"),t("circle",{cx:"455",cy:"160",r:"24",fill:"#F59E0B"}),t("rect",{x:"425",y:"184",width:"60",height:"40",rx:"18",fill:"#F59E0B"}),t("line",{x1:"440",y1:"148",x2:"440",y2:"164",stroke:"#0F172A","stroke-width":"2"}),t("line",{x1:"470",y1:"148",x2:"470",y2:"164",stroke:"#0F172A","stroke-width":"2"}),t("circle",{cx:"446",cy:"156",r:"2.5",fill:"#0F172A"}),t("circle",{cx:"464",cy:"156",r:"2.5",fill:"#0F172A"}),t("path",{d:"M 445 170 Q 455 178 465 170",stroke:"#0F172A","stroke-width":"2",fill:"none","stroke-linecap":"round"}),t("rect",{x:"505",y:"46",width:"226",height:"94",rx:"10",fill:"#FFFFFF",stroke:"#CBD5E1"}),t("path",{d:"M 513 140 L 479 156 L 551 140 Z",fill:"#FFFFFF",stroke:"#CBD5E1"}),t("text",{x:"523",y:"72","font-size":"13",fill:"#334155","font-family":"sans-serif"},"先注册账号拿 AppID"),t("text",{x:"523",y:"96","font-size":"13",fill:"#334155","font-family":"sans-serif"},"没注册成也别慌"),t("text",{x:"523",y:"120","font-size":"13",fill:"#334155","font-family":"sans-serif"},"测试号就能跑通第一个项目")],-1),o(`<h2 id="🎯-学习目标" tabindex="-1">🎯 学习目标 <a class="header-anchor" href="#🎯-学习目标" aria-label="Permalink to &quot;🎯 学习目标&quot;">​</a></h2><p>读完本章，你将能够：</p><ul><li>能独立注册一个<strong>个人主体</strong>的小程序账号</li><li>能在后台找到并保存自己的 <strong>AppID</strong></li><li>能说出开发者工具<strong>三大区域</strong>各管什么</li><li>能用测试号新建项目，跑出第一个 Hello World</li></ul><h2 id="📇-术语卡" tabindex="-1">📇 术语卡 <a class="header-anchor" href="#📇-术语卡" aria-label="Permalink to &quot;📇 术语卡&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>白话解释</th></tr></thead><tbody><tr><td>小程序账号</td><td>小程序的「户口」，在微信公众平台注册，主体分个人、企业等</td></tr><tr><td>AppID</td><td>小程序的身份证号，<code>wx</code> 开头的一串字符，每个小程序唯一</td></tr><tr><td>测试号</td><td>官方发的「临时身份证」，不用注册也能建项目跑代码</td></tr><tr><td>模拟器</td><td>编辑器左侧的手机屏幕「替身」，编译后立刻在这里看效果</td></tr><tr><td>编辑器</td><td>中间写代码的区域，左边文件树、右边代码</td></tr><tr><td>调试器</td><td>右侧查问题的区域，Console 看日志、WXML 看结构</td></tr><tr><td>编译</td><td>把你写的源码「现场加工」成模拟器能跑的程序</td></tr><tr><td>真机调试</td><td>用自己的手机扫码，在真手机上看效果和日志</td></tr></tbody></table><h2 id="🧾-注册小程序账号-个人主体" tabindex="-1">🧾 注册小程序账号（个人主体） <a class="header-anchor" href="#🧾-注册小程序账号-个人主体" aria-label="Permalink to &quot;🧾 注册小程序账号（个人主体）&quot;">​</a></h2><p><strong>第 1 步：进入注册入口</strong></p><p>浏览器打开 <code>https://mp.weixin.qq.com</code>，点右上角「立即注册」。</p><blockquote><p>✅ <strong>你应该看到：</strong> 一个大页面摆着几种账号类型卡片：订阅号、服务号、小程序、企业微信等。</p></blockquote><p><strong>第 2 步：选「小程序」并填写邮箱</strong></p><p>点「小程序」卡片，填写邮箱、密码、验证码。<strong>邮箱必须是没注册过公众平台（公众号/小程序）的</strong>。勾选同意协议后提交。</p><blockquote><p>✅ <strong>你应该看到：</strong> 提示「邮件已发送」，去这个邮箱收件箱里找到激活邮件，点击里面的链接完成激活。</p></blockquote><p><strong>第 3 步：选主体类型「个人」</strong></p><p>激活后回到注册页，选择主体类型。个人学习就选<strong>个人</strong>（不需要营业执照）。</p><blockquote><p>✅ <strong>你应该看到：</strong> 进入「信息登记」页，要求填写管理员身份信息。</p></blockquote><p><strong>第 4 步：信息登记与扫码验证</strong></p><p>填写管理员姓名、身份证号，用<strong>管理员本人微信</strong>扫码验证，填手机验证码确认。</p><blockquote><p>✅ <strong>你应该看到：</strong> 提示「注册完成」，页面跳转进入小程序管理后台（绿色的管理界面）。</p></blockquote><div class="warning custom-block"><p class="custom-block-title">注意</p><p>个人主体的小程序<strong>不能开通微信支付</strong>、不能使用部分高级接口（如获取用户手机号），<code>web-view</code> 打开外部网页也受限。但学习开发完全够用。</p></div><h2 id="🔑-获取-appid" tabindex="-1">🔑 获取 AppID <a class="header-anchor" href="#🔑-获取-appid" aria-label="Permalink to &quot;🔑 获取 AppID&quot;">​</a></h2><p><strong>第 1 步：进入开发设置</strong></p><p>登录 <code>https://mp.weixin.qq.com</code>，左侧菜单点「管理 → 开发管理」，顶部切到「开发设置」。</p><p><strong>第 2 步：复制 AppID</strong></p><p>找到「AppID(小程序ID)」一行，形如 <code>wx1234567890abcdef</code>，点「复制」存进备忘录。</p><blockquote><p>✅ <strong>你应该看到：</strong> AppID 是一串 <code>wx</code> 开头共 18 位的字符，旁边还能看到 AppSecret（学习阶段先不用管，也别发给任何人）。</p></blockquote><h2 id="🗺️-开发者工具界面导览" tabindex="-1">🗺️ 开发者工具界面导览 <a class="header-anchor" href="#🗺️-开发者工具界面导览" aria-label="Permalink to &quot;🗺️ 开发者工具界面导览&quot;">​</a></h2><p>打开微信开发者工具扫码登录后，随便进入一个项目（下一节就会建），记住三大区域：</p><table tabindex="0"><thead><tr><th>区域</th><th>位置</th><th>干什么</th></tr></thead><tbody><tr><td>模拟器</td><td>左侧</td><td>一台虚拟手机，代码改完点「编译」立刻看到效果</td></tr><tr><td>编辑器</td><td>中间</td><td>写代码：左边目录树，右边文件内容</td></tr><tr><td>调试器</td><td>右侧</td><td>查问题：Console 看日志和报错，WXML 面板看页面结构</td></tr></tbody></table><p>顶部工具栏最常用三个按钮：<strong>编译</strong>（重新运行）、<strong>预览</strong>（生成二维码用手机扫码看）、<strong>真机调试</strong>（手机上看还能传日志）。</p><blockquote><p>✅ <strong>你应该看到：</strong> 三个区域从左到右一字排开；如果模拟器没显示，点工具栏右侧的「模拟器」图标把它勾上。</p></blockquote><h2 id="🚀-新建第一个项目-用测试号" tabindex="-1">🚀 新建第一个项目（用测试号） <a class="header-anchor" href="#🚀-新建第一个项目-用测试号" aria-label="Permalink to &quot;🚀 新建第一个项目（用测试号）&quot;">​</a></h2><p><strong>第 1 步：新建</strong></p><p>回到项目列表页，点中间的 <strong>+</strong> 号。</p><p><strong>第 2 步：填四样信息</strong></p><ul><li>项目名称：随便起，如 <code>hello-mini</code></li><li>目录：选一个<strong>新建的空文件夹</strong>（纯英文路径）</li><li>AppID：点「测试号」（没有正式账号也能跑；有就填上章复制的 AppID）</li><li>开发模式：小程序，后端服务选「不使用云服务」（云开发到第 8 章才用）</li></ul><p><strong>第 3 步：选模板并确定</strong></p><p>模板选「JavaScript - 基础模板」，点「确定」。</p><blockquote><p>✅ <strong>你应该看到：</strong> 进度条跑完，模拟器里出现一个带头像、昵称和「Hello World」字样的页面，Console 没有红色报错。</p></blockquote><p><strong>第 4 步：改出你的第一句话</strong></p><p>在编辑器里按 <code>Ctrl / Cmd + F</code> 搜索 <code>Hello World</code>，把这段文字改成 <code>小码的第一个小程序</code>，保存（<code>Ctrl / Cmd + S</code>）。</p><blockquote><p>✅ <strong>你应该看到：</strong> 模拟器自动重新编译，那句问候变成了你写的话——恭喜，这就是<strong>改代码 → 看效果</strong>的完整闭环。</p></blockquote><h2 id="🗂️-模板项目的目录速览" tabindex="-1">🗂️ 模板项目的目录速览 <a class="header-anchor" href="#🗂️-模板项目的目录速览" aria-label="Permalink to &quot;🗂️ 模板项目的目录速览&quot;">​</a></h2><p>在编辑器左侧文件树里看一眼，模板已经帮你搭好了骨架：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hello-mini/</span></span>
<span class="line"><span>├── app.js                  # 整个小程序的入口</span></span>
<span class="line"><span>├── app.json                # 全局配置（页面注册、窗口样式）</span></span>
<span class="line"><span>├── app.wxss                # 全局样式</span></span>
<span class="line"><span>├── project.config.json     # 工程配置（AppID、编译选项）</span></span>
<span class="line"><span>├── sitemap.json            # 声明哪些页面能被微信搜到</span></span>
<span class="line"><span>└── pages/</span></span>
<span class="line"><span>    └── index/              # 首页四件套</span></span>
<span class="line"><span>        ├── index.js        # 页面逻辑</span></span>
<span class="line"><span>        ├── index.json      # 页面配置（标题等）</span></span>
<span class="line"><span>        ├── index.wxml      # 页面结构</span></span>
<span class="line"><span>        └── index.wxss      # 页面样式</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>前 3 个 <code>app.</code> 开头的文件管<strong>全局</strong>，<code>pages/</code> 里每个文件夹是一个页面、且<strong>四件套缺一不可</strong>。新增页面 = 建文件夹 + 在 <code>app.json</code> 的 <code>pages</code> 数组里登记路径，这个动作第 2 章马上会用到。</p><h2 id="💻-动手实践-helloworld-与导入配套示例" tabindex="-1">💻 动手实践：HelloWorld 与导入配套示例 <a class="header-anchor" href="#💻-动手实践-helloworld-与导入配套示例" aria-label="Permalink to &quot;💻 动手实践：HelloWorld 与导入配套示例&quot;">​</a></h2><p><strong>方式 A：模板项目改字（上面第 4 步就是）</strong></p><p>找到模板页面里承载文字的那行代码，把内容换成自己的话：</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-47uJB" id="tab-jyrpCmK" checked><label data-title="pages/index/index.wxml（模板生成，示意）" for="tab-jyrpCmK">pages/index/index.wxml（模板生成，示意）</label></div><div class="blocks"><div class="language-wxml vp-adaptive-theme active line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">wxml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;!-- 找到类似这一行 --&gt;</span></span>
<span class="line"><span>&lt;text class=&quot;user-motto&quot;&gt;Hello World&lt;/text&gt;</span></span>
<span class="line"><span>&lt;!-- 改成 --&gt;</span></span>
<span class="line"><span>&lt;text class=&quot;user-motto&quot;&gt;小码的第一个小程序&lt;/text&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div></div></div><p><strong>方式 B：导入本书配套示例工程</strong></p><p>教程仓库里的 <code>examples/native-demo</code> 是贯穿全书的示例项目。操作：项目列表点 <strong>+</strong> 号 → 目录选择该文件夹 → AppID 选「测试号」→ 确定。导入后按下面清单逐条验收：</p><ul><li>首页出现「你好，小码！」和当前时间</li><li>点「点我 +1」按钮，数字从 0 递增</li><li>点「查看启动日志」，跳转到日志页看到时间列表</li><li>点「编译」重新运行后，日志页多出一条新记录</li><li>调试器 Console 没有红色报错</li></ul><p><strong>从零运行步骤（方式 B）：</strong></p><ol><li>在微信开发者工具首页点 <strong>+</strong> 号</li><li>目录选择 <code>examples/native-demo</code> 文件夹，AppID 选「测试号」，后端服务选「不使用云服务」</li><li>点「确定」，等待编译完成</li><li>✅ <strong>你应该看到：</strong> 模拟器显示「你好，小码！」页面</li><li>按上面 5 条清单逐项操作验证</li><li>✅ <strong>你应该看到：</strong> 清单全部打勾，说明环境与工具链完全就绪</li></ol><h2 id="✏️-分级练习" tabindex="-1">✏️ 分级练习 <a class="header-anchor" href="#✏️-分级练习" aria-label="Permalink to &quot;✏️ 分级练习&quot;">​</a></h2><ol><li>🟢 <strong>跟做型</strong>：把首页问候语改成你的名字，再打开根目录的 <code>app.json</code>，把 <code>navigationBarTitleText</code> 改成「我的地盘」，观察模拟器顶部标题变化。</li><li>🟡 <strong>修改型</strong>：在首页问候语下方自己加一行新文字（仿照现有结构多写一个 view 标签），内容随意。</li><li>🔴 <strong>创作型</strong>：打开调试器的「WXML」面板，找到你新加的那行文字对应的节点并点它，观察模拟器高亮——体验「页面结构可以被审查」。</li></ol><h2 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h2><ul><li><strong>注册时提示「该邮箱已被占用」</strong> → 邮箱注册过公众号或被微信生态绑定 → 换一个从没用过的邮箱</li><li><strong>Console 报 <code>invalid appid</code>，模拟器白屏</strong> → AppID 复制时带了空格或填错 → 重新完整复制，注意结尾别带空格</li><li><strong>新建项目点「确定」没反应或提示「目录非空」</strong> → 所选文件夹里有旧文件 → 换一个全新的空文件夹</li><li><strong>测试号项目里调用某些接口提示无权限</strong> → 测试号能力有限制 → 正式注册的 AppID 才有完整能力</li></ul><h2 id="下一章预告" tabindex="-1">下一章预告 <a class="header-anchor" href="#下一章预告" aria-label="Permalink to &quot;下一章预告&quot;">​</a></h2><p>项目跑起来了，但你肯定好奇：页面上的字凭什么能自己变？程序启动、切后台时都发生了什么？下一章拆开 WXML、WXSS 与生命周期的黑盒。</p>`,60)])])}const x=e(r,[["render",i]]);export{u as __pageData,x as default};
